def longest(strings: List[str]) -> Optional[str]:
    """ Out of list of strings, return the longest one. Return the first one in case of multiple
    strings of the same length. Return None in case the input list is empty.
    """
    if not strings:
        return None

    def compare_strings(x: str, y: str) -> bool:
        return len(x) >= len(y)

    max_length = -1
    longest_str = None
    for s in strings:
        if len(s) > max_length:
            longest_str = s
            max_length = len(s)
        elif len(s) == max_length:
            longest_str = s  # In case of multiple strings of the same length

    return longest_str
