def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise. Knowing that (a) is less than 100.
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        """Check if a number is prime or not."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    def prime_factors(n):
        """Return a list of prime factors of a number."""
        factors = []
        # Check for number of 2s
        while n % 2 == 0:
            factors.append(2)
            n = n // 2
        # Check for other primes
        for i in range(3, int(n**0.5) + 1, 2):
            while n % i == 0:
                factors.append(i)
                n = n // i
        if n > 2:
            factors.append(n)
        return factors

    factors_of_a = prime_factors(a)
    if len(factors_of_a) == 3 and all(is_prime(f) for f in factors_of_a):
        return True
    else:
        return False

# Example usage:
print(is_multiply_prime(30))  # True
print(is_multiply_prime(60))  # False, because prime factors are 2, 3, 5 but we need exactly 3 prime numbers)
