def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """

    if not test:
        return {}

    # Split the input string into a list of letters
    letters = test.split()

    # Create a histogram (a dictionary)
    # Using an initial value of 0 for the default letter count
    histogram_dict = dict.fromkeys(letters, 0)

    # Count the occurrences of each letter
    for letter in letters:
        histogram_dict[letter] += 1

    # Filter the dictionary to only include letters with the maximum count
    max_count = max(histogram_dict.values())
    result = {letter: count for letter, count in histogram_dict.items() if count == max_count}

    return result
```

