import heapq

def minPath(grid, k):
    N = len(grid)

    # Directions: right, down, left, up
    dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # Find the position and value of 1
    value_to_position = {}
    for i in range(N):
        for j in range(N):
            value_to_position[grid[i][j]] = (i, j)

    start_position = value_to_position[1]

    # Initialize the priority queue (min-heap) with the starting state
    pq = [(0, 1, start_position[1], start_position[0])]

    # Initialize the grid to keep track of the minimum steps to achieve each state
    memo = [[float('inf')] * N for _ in range(N)]
    memo[start_position[0]][start_position[1]] = 0

    while pq:
        steps, visited_steps, x, y = heapq.heappop(pq)

        if visited_steps + 1 >= k:
            return [i for i in range(k-1, -1, -1)]

        if steps == k:
            continue

        for dx, dy in dirs:
            nx, ny = x + dx, y + dy

            if 0 <= nx < N and 0 <= ny < N:
                if memo[nx][ny] > visited_steps + 1:
                    memo[nx][ny] = visited_steps + 1
                    heapq.heappush(pq, (memo[nx][ny], visited_steps + 1, nx, ny))

    # Backtrack to find the path
    path = []
    while not (path and path[-1] < 1):
        path.append(1)
        current_steps = 1
        for x, y in zip(range(N - 1, -1, -1), range(N)):
            if memo[y][x] == current_steps:
                step = grid[y][x]
                path.append(step)
                current_steps += 1
                break

    return path[::-1]
